create or replace function public.get_operations_copilot_route_intelligence() returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ begin if public.current_role()<>'platform_admin' then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; return coalesce((select jsonb_agg(x.obj order by x.risk_rank desc,x.minutes_to_start asc nulls last) from (select jsonb_build_object('job_id',j.id,'guard_id',g.id,'mission_state',coalesce(me.state,j.status::text),'guard_latitude',g.current_latitude,'guard_longitude',g.current_longitude,'property_latitude',pr.latitude,'property_longitude',pr.longitude,'last_location_at',g.last_location_at,'distance_miles',case when g.current_latitude is null or g.current_longitude is null or pr.latitude is null or pr.longitude is null then null else round((3959*2*asin(sqrt(power(sin(radians(pr.latitude-g.current_latitude)/2),2)+cos(radians(g.current_latitude))*cos(radians(pr.latitude))*power(sin(radians(pr.longitude-g.current_longitude)/2),2))))::numeric,1) end,'eta_minutes',case when g.current_latitude is null or g.current_longitude is null or pr.latitude is null or pr.longitude is null then null else greatest(1,ceil((3959*2*asin(sqrt(power(sin(radians(pr.latitude-g.current_latitude)/2),2)+cos(radians(g.current_latitude))*cos(radians(pr.latitude))*power(sin(radians(pr.longitude-g.current_longitude)/2),2))))/25*60)::integer) end,'minutes_to_start',case when j.scheduled_for is null then null else floor(extract(epoch from (j.scheduled_for-now()))/60)::integer end,'movement',case when lp.points<2 then 'unknown' when lp.moved_miles<0.05 then 'stationary' else 'moving' end,'moved_miles_10m',lp.moved_miles,'location_points_10m',coalesce(lp.points,0),'distance_change_miles',lp.distance_change_miles,'progress',case when lp.points<3 then 'unknown' when lp.moved_miles<0.05 then 'stationary' when lp.distance_change_miles>=0.10 then 'approaching' when lp.distance_change_miles<=-0.10 then 'moving_away' else 'not_approaching' end) obj,case when g.last_location_at is null or g.last_location_at<now()-interval '10 minutes' then 5 when lp.points>=3 and lp.distance_change_miles<=-0.10 and coalesce(me.state,'')='en_route' then 4 when j.scheduled_for is not null and j.scheduled_for<=now()+interval '15 minutes' and coalesce(me.state,'') not in ('active','checkpoint','review','completed') then 3 when lp.points>=2 and lp.moved_miles<0.05 and coalesce(me.state,'')='en_route' then 2 else 1 end risk_rank,case when j.scheduled_for is null then null else floor(extract(epoch from (j.scheduled_for-now()))/60)::integer end minutes_to_start from public.marketplace_jobs j join public.properties pr on pr.id=j.property_id join public.job_assignments ja on ja.job_id=j.id and ja.status not in ('completed','cancelled','declined') join public.guards g on g.id=ja.guard_id left join public.mission_engine_state me on me.job_id=j.id left join lateral (select count(*)::int points,round((3959*2*asin(sqrt(power(sin(radians((array_agg(e.latitude order by e.recorded_at desc))[1]-(array_agg(e.latitude order by e.recorded_at))[1])/2),2)+cos(radians((array_agg(e.latitude order by e.recorded_at))[1]))*cos(radians((array_agg(e.latitude order by e.recorded_at desc))[1]))*power(sin(radians((array_agg(e.longitude order by e.recorded_at desc))[1]-(array_agg(e.longitude order by e.recorded_at))[1])/2),2))))::numeric,2) moved_miles,round(((3959*2*asin(sqrt(power(sin(radians(pr.latitude-(array_agg(e.latitude order by e.recorded_at))[1])/2),2)+cos(radians((array_agg(e.latitude order by e.recorded_at))[1]))*cos(radians(pr.latitude))*power(sin(radians(pr.longitude-(array_agg(e.longitude order by e.recorded_at))[1])/2),2))))-(3959*2*asin(sqrt(power(sin(radians(pr.latitude-(array_agg(e.latitude order by e.recorded_at desc))[1])/2),2)+cos(radians((array_agg(e.latitude order by e.recorded_at desc))[1]))*cos(radians(pr.latitude))*power(sin(radians(pr.longitude-(array_agg(e.longitude order by e.recorded_at desc))[1])/2),2)))))::numeric,2) distance_change_miles from public.guard_location_history e where e.guard_id=g.id and e.job_id=j.id and e.recorded_at>=now()-interval '10 minutes') lp on true where j.status in ('accepted','assigned','active')) x),'[]'::jsonb); end $$; revoke all on function public.get_operations_copilot_route_intelligence() from public,anon; grant execute on function public.get_operations_copilot_route_intelligence() to authenticated;
